import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { useWhatsApp } from '../context/WhatsAppContext';
import { useSocket } from '../context/SocketContext';
import { frontendLogger } from '../utils/frontendLogger';
import {
  Box,
  Typography,
  Card,
  CardContent,
  Avatar,
  Chip,
  IconButton,
  TextField,
  InputAdornment,
  Menu,
  MenuItem,
  Badge,
  Tooltip,
  CircularProgress,
  Alert,
  Divider,
  List,
  ListItem,
  ListItemAvatar,
  ListItemText,
  ListItemSecondaryAction,
  Tabs,
  Tab,
  Paper,
  Button,
  Stack,
  FormControl,
  InputLabel,
  Select,
  Grid
} from '@mui/material';
import {
  Search,
  FilterList,
  Refresh,
  Message,
  Phone,
  Image,
  AttachFile,
  Videocam,
  Mic,
  LocationOn,
  Group,
  Person,
  CheckCircle,
  DoneAll,
  Error as ErrorIcon,
  Schedule,
  Star,
  StarBorder,
  Archive,
  Delete,
  Download,
  WhatsApp,
  Send,
  Reply,
  Forward,
  Block,
  Report,
  MoreVert,
  CalendarToday,
  AccessTime,
  TrendingUp,
  TrendingDown
} from '@mui/icons-material';
import { format, formatDistanceToNow, isToday, isYesterday, parseISO } from 'date-fns';
import { es } from 'date-fns/locale';

interface Message {
  id: string;
  chatJid?: string;
  senderJid?: string;
  from_me: boolean;
  text_content?: string;
  timestamp: string;
  status: 'pending' | 'sent' | 'delivered' | 'read' | 'error';
  message_type: 'conversation' | 'image' | 'document' | 'video' | 'audio' | 'ptt';
  media_url?: string;
  media_mime_type?: string;
  caption?: string;
  file_name?: string;
  file_size?: number;
  sender_name?: string;
  sender_avatar?: string;
  quoted_message_id?: string;
  agent_id?: number | null;
  agent_name?: string;
  chat_name?: string;
  chat_avatar?: string;
}

interface MessageStats {
  total: number;
  today: number;
  unread: number;
  sent: number;
  received: number;
  media: number;
  errors: number;
}

const MessagesModule: React.FC = () => {
  // Obtener sessionId de localStorage/sessionStorage en lugar del contexto
  const sessionId = localStorage.getItem('whatsflow_session') || sessionStorage.getItem('whatsflow_session');
  const { socket, isConnected } = useSocket();
  
  const [messages, setMessages] = useState<Message[]>([]);
  const [filteredMessages, setFilteredMessages] = useState<Message[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [messageTypeFilter, setMessageTypeFilter] = useState<string>('all');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [dateFilter, setDateFilter] = useState<string>('all');
  const [selectedTab, setSelectedTab] = useState(0);
  const [anchorEl, setAnchorEl] = useState<null | HTMLElement>(null);
  const [selectedMessage, setSelectedMessage] = useState<Message | null>(null);
  const [stats, setStats] = useState<MessageStats>({
    total: 0,
    today: 0,
    unread: 0,
    sent: 0,
    received: 0,
    media: 0,
    errors: 0
  });

  // Cargar todos los mensajes
  const loadAllMessages = useCallback(async () => {
    if (!sessionId) return;
    
    setLoading(true);
    setError(null);
    
    try {
      const response = await fetch(`/api/messages/all?sessionId=${sessionId}&limit=1000`);
      const data = await response.json();
      
      if (data.success) {
        const allMessages = data.messages || [];
        setMessages(allMessages);
        frontendLogger.log('MESSAGES_LOADED', { count: allMessages.length });
      } else {
        setError(data.message || 'Error al cargar mensajes');
      }
    } catch (err) {
      console.error('Error loading messages:', err);
      setError('Error de conexión al cargar mensajes');
    } finally {
      setLoading(false);
    }
  }, [sessionId]);

  // Calcular estadísticas
  const calculateStats = useCallback((msgs: Message[]) => {
    const today = new Date();
    const todayMessages = msgs.filter(msg => 
      isToday(parseISO(msg.timestamp))
    );
    
    const stats: MessageStats = {
      total: msgs.length,
      today: todayMessages.length,
      unread: msgs.filter(msg => !msg.from_me && msg.status !== 'read').length,
      sent: msgs.filter(msg => msg.from_me).length,
      received: msgs.filter(msg => !msg.from_me).length,
      media: msgs.filter(msg => msg.message_type !== 'conversation').length,
      errors: msgs.filter(msg => msg.status === 'error').length
    };
    
    setStats(stats);
  }, []);

  // Filtrar mensajes
  useEffect(() => {
    let filtered = messages;
    
    // Filtro de búsqueda
    if (searchTerm) {
      filtered = filtered.filter(msg => 
        msg.text_content?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        msg.sender_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        msg.chat_name?.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }
    
    // Filtro por tipo de mensaje
    if (messageTypeFilter !== 'all') {
      filtered = filtered.filter(msg => msg.message_type === messageTypeFilter);
    }
    
    // Filtro por estado
    if (statusFilter !== 'all') {
      filtered = filtered.filter(msg => msg.status === statusFilter);
    }
    
    // Filtro por fecha
    if (dateFilter !== 'all') {
      const now = new Date();
      filtered = filtered.filter(msg => {
        const msgDate = parseISO(msg.timestamp);
        switch (dateFilter) {
          case 'today':
            return isToday(msgDate);
          case 'yesterday':
            return isYesterday(msgDate);
          case 'week':
            return (now.getTime() - msgDate.getTime()) < 7 * 24 * 60 * 60 * 1000;
          case 'month':
            return (now.getTime() - msgDate.getTime()) < 30 * 24 * 60 * 60 * 1000;
          default:
            return true;
        }
      });
    }
    
    setFilteredMessages(filtered);
  }, [messages, searchTerm, messageTypeFilter, statusFilter, dateFilter]);

  // Escuchar nuevos mensajes en tiempo real
  useEffect(() => {
    if (!socket || !isConnected) return;

    const handleNewMessage = (newMessage: Message) => {
      setMessages(prev => {
        // Evitar duplicados
        if (prev.some(msg => msg.id === newMessage.id)) {
          return prev;
        }
        return [newMessage, ...prev];
      });
    };

    const handleMessageUpdate = (updatedMessage: Message) => {
      setMessages(prev => prev.map(msg => 
        msg.id === updatedMessage.id ? updatedMessage : msg
      ));
    };

    socket.on('new_message', handleNewMessage);
    socket.on('message_updated', handleMessageUpdate);

    return () => {
      socket.off('new_message', handleNewMessage);
      socket.off('message_updated', handleMessageUpdate);
    };
  }, [socket, isConnected]);

  // Calcular estadísticas cuando cambian los mensajes
  useEffect(() => {
    calculateStats(messages);
  }, [messages, calculateStats]);

  // Cargar mensajes al montar el componente
  useEffect(() => {
    loadAllMessages();
  }, [loadAllMessages]);

  // Función para formatear fecha
  const formatMessageDate = (timestamp: string) => {
    const date = parseISO(timestamp);
    if (isToday(date)) {
      return format(date, 'HH:mm');
    } else if (isYesterday(date)) {
      return 'Ayer';
    } else {
      return format(date, 'dd/MM/yyyy');
    }
  };

  // Función para obtener icono según tipo de mensaje
  const getMessageTypeIcon = (type: string) => {
    switch (type) {
      case 'image': return <Image fontSize="small" />;
      case 'video': return <Videocam fontSize="small" />;
      case 'audio': return <Mic fontSize="small" />;
      case 'document': return <AttachFile fontSize="small" />;
      case 'location': return <LocationOn fontSize="small" />;
      default: return <Message fontSize="small" />;
    }
  };

  // Función para obtener color según estado
  const getStatusColor = (status: string) => {
    switch (status) {
      case 'sent': return 'primary';
      case 'delivered': return 'info';
      case 'read': return 'success';
      case 'error': return 'error';
      default: return 'default';
    }
  };

  // Función para obtener icono según estado
  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'sent': return <CheckCircle fontSize="small" />;
      case 'delivered': return <DoneAll fontSize="small" />;
      case 'read': return <DoneAll fontSize="small" color="success" />;
      case 'error': return <ErrorIcon fontSize="small" />;
      default: return <Schedule fontSize="small" />;
    }
  };

  // Manejar menú contextual
  const handleMenuOpen = (event: React.MouseEvent<HTMLElement>, message: Message) => {
    setAnchorEl(event.currentTarget);
    setSelectedMessage(message);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
    setSelectedMessage(null);
  };

  // Componente de tarjeta de estadísticas
  const StatCard = ({ title, value, icon, color }: { title: string; value: number; icon: React.ReactElement; color: string }) => (
    <Card sx={{ height: '100%', background: `linear-gradient(135deg, ${color}20 0%, ${color}10 100%)` }}>
      <CardContent sx={{ textAlign: 'center', p: 2 }}>
        <Box sx={{ color, mb: 1 }}>{icon}</Box>
        <Typography variant="h4" sx={{ fontWeight: 700, color, mb: 1 }}>
          {value.toLocaleString()}
        </Typography>
        <Typography variant="body2" sx={{ color: 'text.secondary' }}>
          {title}
        </Typography>
      </CardContent>
    </Card>
  );
  return (
    <Box sx={{ p: 3 }}>
      {/* Header */}
      <Box sx={{ mb: 4 }}>
        <Typography variant="h4" sx={{ fontWeight: 700, mb: 1 }}>
          📨 Todos los Mensajes
        </Typography>
        <Typography variant="body1" color="text.secondary">
          Visualiza y gestiona todos los mensajes del sistema en tiempo real
        </Typography>
      </Box>

      {/* Estadísticas */}
      <Grid container spacing={3} sx={{ mb: 4 }}>
        <Grid item xs={12} sm={6} md={3}>
          <StatCard
            title="Total Mensajes"
            value={stats.total}
            icon={<Message />}
            color="#2196f3"
          />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <StatCard
            title="Hoy"
            value={stats.today}
            icon={<CalendarToday />}
            color="#4caf50"
          />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <StatCard
            title="Sin Leer"
            value={stats.unread}
            icon={<Badge badgeContent={stats.unread} color="error"><Message /></Badge>}
            color="#ff9800"
          />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <StatCard
            title="Multimedia"
            value={stats.media}
            icon={<Image />}
            color="#9c27b0"
          />
        </Grid>
      </Grid>

      {/* Controles de filtro */}
      <Card sx={{ mb: 3 }}>
        <CardContent>
          <Stack direction={{ xs: 'column', md: 'row' }} spacing={2} alignItems="center">
            <TextField
              fullWidth
              size="small"
              placeholder="Buscar en mensajes, contactos o chats..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <Search />
                  </InputAdornment>
                ),
              }}
            />
            
            <FormControl size="small" sx={{ minWidth: 120 }}>
              <InputLabel>Tipo</InputLabel>
              <Select
                value={messageTypeFilter}
                label="Tipo"
                onChange={(e) => setMessageTypeFilter(e.target.value)}
              >
                <MenuItem value="all">Todos</MenuItem>
                <MenuItem value="conversation">Texto</MenuItem>
                <MenuItem value="image">Imagen</MenuItem>
                <MenuItem value="video">Video</MenuItem>
                <MenuItem value="audio">Audio</MenuItem>
                <MenuItem value="document">Documento</MenuItem>
              </Select>
            </FormControl>

            <FormControl size="small" sx={{ minWidth: 120 }}>
              <InputLabel>Estado</InputLabel>
              <Select
                value={statusFilter}
                label="Estado"
                onChange={(e) => setStatusFilter(e.target.value)}
              >
                <MenuItem value="all">Todos</MenuItem>
                <MenuItem value="sent">Enviados</MenuItem>
                <MenuItem value="delivered">Entregados</MenuItem>
                <MenuItem value="read">Leídos</MenuItem>
                <MenuItem value="error">Errores</MenuItem>
              </Select>
            </FormControl>

            <FormControl size="small" sx={{ minWidth: 120 }}>
              <InputLabel>Fecha</InputLabel>
              <Select
                value={dateFilter}
                label="Fecha"
                onChange={(e) => setDateFilter(e.target.value)}
              >
                <MenuItem value="all">Todo</MenuItem>
                <MenuItem value="today">Hoy</MenuItem>
                <MenuItem value="yesterday">Ayer</MenuItem>
                <MenuItem value="week">Esta semana</MenuItem>
                <MenuItem value="month">Este mes</MenuItem>
              </Select>
            </FormControl>

            <Button
              variant="outlined"
              startIcon={<Refresh />}
              onClick={loadAllMessages}
              disabled={loading}
            >
              Actualizar
            </Button>
          </Stack>
        </CardContent>
      </Card>

      {/* Resultados */}
      <Card>
        <CardContent sx={{ p: 0 }}>
          <Box sx={{ p: 2, borderBottom: 1, borderColor: 'divider' }}>
            <Typography variant="h6">
              {filteredMessages.length} mensajes encontrados
              {searchTerm && ` para "${searchTerm}"`}
            </Typography>
          </Box>

          {loading ? (
            <Box sx={{ display: 'flex', justifyContent: 'center', p: 4 }}>
              <CircularProgress />
            </Box>
          ) : error ? (
            <Alert severity="error" sx={{ m: 2 }}>
              {error}
            </Alert>
          ) : filteredMessages.length === 0 ? (
            <Box sx={{ textAlign: 'center', p: 4 }}>
              <Message sx={{ fontSize: 64, color: '#ccc', mb: 2 }} />
              <Typography variant="h6" color="textSecondary">
                No se encontraron mensajes
              </Typography>
              <Typography variant="body2" color="textSecondary">
                {searchTerm ? 'Intenta con otros términos de búsqueda' : 'Los mensajes aparecerán aquí cuando lleguen'}
              </Typography>
            </Box>
          ) : (
            <List sx={{ maxHeight: '60vh', overflow: 'auto' }}>
              {filteredMessages.map((message) => (
                <ListItem
                  key={message.id}
                  divider
                  sx={{
                    '&:hover': {
                      backgroundColor: 'action.hover',
                    },
                  }}
                >
                  <ListItemAvatar>
                    <Badge
                      overlap="circular"
                      anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
                      badgeContent={
                        <Tooltip title={message.from_me ? 'Enviado por mí' : 'Recibido'}>
                          <Box
                            sx={{
                              width: 12,
                              height: 12,
                              borderRadius: '50%',
                              bgcolor: message.from_me ? '#25d366' : '#667781',
                              border: '2px solid white'
                            }}
                          />
                        </Tooltip>
                      }
                    >
                      <Avatar
                        src={message.from_me ? undefined : message.sender_avatar}
                        sx={{
                          bgcolor: message.from_me ? '#25d366' : '#667781'
                        }}
                      >
                        {message.from_me ? 'Yo' : (message.sender_name?.charAt(0) || 'C')}
                      </Avatar>
                    </Badge>
                  </ListItemAvatar>

                  <ListItemText
                    primary={
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5 }}>
                        <Typography variant="subtitle1" sx={{ fontWeight: 600 }}>
                          {message.from_me ? 'Yo' : message.sender_name || 'Contacto'}
                        </Typography>
                        {!message.from_me && message.chat_name && (
                          <Chip
                            size="small"
                            label={message.chat_name}
                            variant="outlined"
                            color="primary"
                          />
                        )}
                        <Box sx={{ flex: 1 }} />
                        <Typography variant="caption" color="text.secondary">
                          {formatMessageDate(message.timestamp)}
                        </Typography>
                      </Box>
                    }
                    secondary={
                      <Box>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
                          {getMessageTypeIcon(message.message_type)}
                          <Typography variant="body2" sx={{ flex: 1 }}>
                            {message.text_content || message.caption || 'Mensaje multimedia'}
                          </Typography>
                        </Box>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                          <Chip
                            size="small"
                            icon={getStatusIcon(message.status)}
                            label={message.status}
                            color={getStatusColor(message.status) as any}
                            variant="outlined"
                          />
                          {message.agent_name && (
                            <Chip
                              size="small"
                              label={`Agente: ${message.agent_name}`}
                              color="secondary"
                              variant="outlined"
                            />
                          )}
                        </Box>
                      </Box>
                    }
                  />

                  <ListItemSecondaryAction>
                    <IconButton
                      edge="end"
                      onClick={(e) => handleMenuOpen(e, message)}
                    >
                      <MoreVert />
                    </IconButton>
                  </ListItemSecondaryAction>
                </ListItem>
              ))}
            </List>
          )}
        </CardContent>
      </Card>

      {/* Menú contextual */}
      <Menu
        anchorEl={anchorEl}
        open={Boolean(anchorEl)}
        onClose={handleMenuClose}
      >
        <MenuItem onClick={handleMenuClose}>
          <Reply sx={{ mr: 1 }} />
          Responder
        </MenuItem>
        <MenuItem onClick={handleMenuClose}>
          <Forward sx={{ mr: 1 }} />
          Reenviar
        </MenuItem>
        <Divider />
        <MenuItem onClick={handleMenuClose}>
          <Star sx={{ mr: 1 }} />
          Marcar importante
        </MenuItem>
        <MenuItem onClick={handleMenuClose}>
          <Archive sx={{ mr: 1 }} />
          Archivar
        </MenuItem>
        <Divider />
        <MenuItem onClick={handleMenuClose} sx={{ color: 'error.main' }}>
          <Delete sx={{ mr: 1 }} />
          Eliminar
        </MenuItem>
      </Menu>
    </Box>
  );
};

export default MessagesModule;